with valid_shipments as (select *, substring(status, 1, 4) as status_prefix from shipments where cost <= 46 and order_id = 29), Summary as (select status, case when year(delivered_date) < 2024 then 'before_2024' when year(delivered_date) = 2024 then '2024' else 'after_2024' end as delivered_cohort, count(cost) as cost_count from valid_shipments group by status, case when year(delivered_date) < 2024 then 'before_2024' when year(delivered_date) = 2024 then '2024' else 'after_2024' end) select * from Summary where cost_count >= 3 order by status, delivered_cohort limit 50;
